enum { AT_LANES=8, AT_OPS=9, AT_RESOURCES=4, AT_FIELDS=AT_OPS*2, AT_RESULTS=AT_LANES*AT_RESOURCES*AT_FIELDS };
static const uint32_t at_seeds[AT_OPS]={0xfffffffdu,0x80000020u,0x80000020u,0xf0f00ff0u,0x30000300u,0x55aa00ffu,0x7f000010u,0x11001100u,0x22002200u};
static uint32_t at_initial(unsigned j,unsigned op,unsigned lane,unsigned round)
{ return at_seeds[op]^(j*0x00000100u)^(round*0x00010000u)^(lane*0x11u); }
static int64_t at_signed(uint32_t x)
{ return x&0x80000000u?(int64_t)x-0x100000000ll:(int64_t)x; }
static uint32_t at_final(unsigned j,unsigned op,unsigned lane,unsigned round)
{
 uint32_t old=at_initial(j,op,lane,round),operand=0x7ffffff0u;
 switch(op) {
 case 0:return old+7u;
 case 1:return (j&1)?(at_signed(old)<at_signed(operand)?old:operand):(old<operand?old:operand);
 case 2:return (j&1)?(at_signed(old)>at_signed(operand)?old:operand):(old>operand?old:operand);
 case 3:return old&0x0ff0f00fu;
 case 4:return old|0x0040c005u;
 case 5:return old^0xa5055a00u;
 case 6:return 0x80000080u+lane;
 case 7:return 0x80000100u+lane;
 default:return old;
 }
}
